/**
 * The csharp extension writes `Player.ts` next to `Player.cs`, starting with
 * `// <auto-generated> from Player.cs ...`. It keeps no line map, so a .ts line is
 * mapped to the .cs file approximately: find the enclosing class member in both
 * files, then the .cs line in that member whose identifiers best match the .ts line.
 */

const HEADER_RE = /^﻿?\s*\/\/\s*<auto-generated>\s*from\s+([^\s]+?\.cs)\b/i;

/** "Player.cs" when the first line of a .ts file is the csharp extension's header, else ''. */
export function generatedFrom(firstLine: string): string {
    const m = HEADER_RE.exec(firstLine || '');
    return m ? m[1] : '';
}

const TS_SKIP = /^(if|for|while|switch|catch|return|function|else|do|try|with|typeof|new|super|await|yield)$/;

/** The class member (method, accessor, constructor) a TS line belongs to. */
function tsMemberAt(lines: string[], index: number): { name: string; line: number; className: string } | null {
    let member: { name: string; line: number } | null = null;
    for (let i = index; i >= 0; i--) {
        const s = lines[i];
        if (!member) {
            const m = /^\s*(?:(?:public|private|protected|static|async|readonly|override|abstract|get|set)\s+)*(constructor|[A-Za-z_$][\w$]*)\s*(?:<[^>()]*>)?\s*\([^;]*$/.exec(s);
            if (m && !TS_SKIP.test(m[1]) && /\{\s*$|\)\s*(?::[^=]+)?$/.test(s)) member = { name: m[1], line: i };
        }
        const c = /\bclass\s+([A-Za-z_$][\w$]*)/.exec(s);
        if (c) return member ? { name: member.name, line: member.line, className: c[1] } : null;
    }
    return member ? { name: member.name, line: member.line, className: '' } : null;
}

/** Line index of a member declaration in C#, searched after `from`. -1 when not found. */
function csMemberLine(lines: string[], name: string, className: string, from: number): number {
    const isCtor = name === 'constructor';
    const ident = isCtor ? className : name;
    if (!ident) return -1;
    const re = new RegExp('^\\s*(?:\\[[^\\]]*\\]\\s*)*(?:(?:public|private|protected|internal|static|override|virtual|async|abstract|sealed|new|extern|unsafe|partial)\\s+)*' + (isCtor ? '' : '[\\w<>\\[\\],.?]+\\s+') + escapeRe(ident) + '\\s*(?:<[^>()]*>)?\\s*\\(');
    for (let i = Math.max(0, from); i < lines.length; i++) if (re.test(lines[i])) return i;
    // getters / setters: "public double Speed { get => ...; }" or a property named like the accessor
    const prop = new RegExp('\\b' + escapeRe(ident) + '\\b\\s*(?:\\{|=>)');
    for (let i = Math.max(0, from); i < lines.length; i++) if (prop.test(lines[i])) return i;
    return -1;
}

function escapeRe(s: string): string {
    return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const TOKEN_SKIP = /^(this|const|let|var|new|return|void|number|string|boolean|double|float|int|long|bool|null|undefined|true|false|as|of|in|is|public|private|protected|static|readonly|override)$/;

/** The identifiers and words of a line (lower case, without keywords). */
export function tokens(line: string): string[] {
    const out: string[] = [];
    const re = /[A-Za-z_$][\w$]*|\d+(?:\.\d+)?/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(line))) {
        const t = m[0].toLowerCase().replace(/^_+/, '') || m[0];
        if (!TOKEN_SKIP.test(t)) out.push(t);
    }
    return out;
}

function similarity(a: string[], b: string[]): number {
    if (!a.length || !b.length) return 0;
    const setB: Record<string, number> = {};
    for (let i = 0; i < b.length; i++) setB[b[i]] = (setB[b[i]] || 0) + 1;
    let common = 0;
    for (let i = 0; i < a.length; i++) {
        if (setB[a[i]]) {
            setB[a[i]]--;
            common++;
        }
    }
    return (2 * common) / (a.length + b.length);
}

/** The end (exclusive) of the block that starts at or after `start`, by brace counting. */
function blockEnd(lines: string[], start: number): number {
    let depth = 0;
    let opened = false;
    for (let i = start; i < lines.length; i++) {
        const s = lines[i].replace(/"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\/\/.*$/g, '');
        for (let k = 0; k < s.length; k++) {
            if (s[k] === '{') {
                depth++;
                opened = true;
            } else if (s[k] === '}') {
                depth--;
                if (opened && depth <= 0) return i + 1;
            }
        }
        if (!opened && i > start && /;\s*$/.test(s)) return i + 1; // expression-bodied member
    }
    return lines.length;
}

function isCodeLine(s: string): boolean {
    const t = s.trim();
    return !!t && !/^[{}]+;?$/.test(t) && !/^\/\//.test(t) && !/^\[.*\]$/.test(t);
}

/**
 * The approximate .cs line (1-based) for a 1-based line of the generated .ts.
 * Exact when the statement's identifiers match a single .cs line of the same member.
 */
export function mapTsLineToCs(ts: string, cs: string, tsLine: number): number {
    const tl = ts.split(/\r?\n/);
    const cl = cs.split(/\r?\n/);
    const idx = Math.min(Math.max(0, tsLine - 1), tl.length - 1);
    const want = tokens(tl[idx] || '');

    let from = 0;
    let to = cl.length;
    let expected = -1;
    const member = tsMemberAt(tl, idx);
    if (member) {
        let classLine = 0;
        if (member.className) {
            const cre = new RegExp('\\bclass\\s+' + escapeRe(member.className) + '\\b');
            for (let i = 0; i < cl.length; i++) if (cre.test(cl[i])) {
                classLine = i;
                break;
            }
        }
        const ml = csMemberLine(cl, member.name, member.className, classLine);
        if (ml >= 0) {
            from = ml;
            to = blockEnd(cl, ml);
            // the same number of code lines below the member header, as a fallback
            let n = 0;
            for (let i = member.line + 1; i <= idx; i++) if (isCodeLine(tl[i])) n++;
            expected = ml;
            for (let i = ml + 1; i < to && n > 0; i++) {
                if (isCodeLine(cl[i])) {
                    n--;
                    expected = i;
                }
            }
            if (idx === member.line) return ml + 1;
        }
    }

    let best = -1;
    let bestScore = 0;
    for (let i = from; i < to; i++) {
        let score = similarity(want, tokens(cl[i]));
        if (expected >= 0) score -= Math.min(0.15, Math.abs(i - expected) * 0.01);
        if (score > bestScore) {
            bestScore = score;
            best = i;
        }
    }
    if (best >= 0 && bestScore >= 0.3) return best + 1;
    if (expected >= 0) return expected + 1;
    return best >= 0 ? best + 1 : 1;
}
